    final Stack<AbstractType> outputStack = getOutputStack();
    if (descriptor.getDescriptor().getSub().getSort() == Type.OBJECT) {
        AbstractType poppedType = outputStack.pop();
        if (!poppedType.getDescriptor().getSub().equals(descriptor)) {
            throw new IllegalStateException("Top of output stack does not match descriptor: " + descriptor);
        }
    } else {
        final String[] argTypes = descriptor.getDescriptor().getSub().getArgTypes();
        for (String argType : argTypes) {
            if (outputStack.isEmpty()) {
                throw new IllegalStateException("Output stack is empty but required type was requested: " + argType);
            }
            AbstractType poppedType = outputStack.pop();
            if (!poppedType.getDescriptor().getSub().equals(argType)) {
                throw new IllegalStateException("Top of output stack does not match argument type: " + argType);
            }
        }
    }
}

