private void checkIfPackedField() throws IOException {
    boolean packed = input.isFieldPacked();
    if (packed) {
        readLength = input.readInt32();
        readLength = Ints.checkedCast(readLength);
        packedLimit += readLength;
        input.pushLimit(readLength);
    }
}

